records=[
 dict(id='record-01',eyebrow='THE CREW',when='JANUARY 1967',title='Three men. One ground test.',dek='This was a countdown rehearsal, not a launch. The rocket was unfueled; the spacecraft was not free of danger.',detail='Gus Grissom, Ed White and Roger Chaffee prepared to rehearse an Apollo countdown at Launch Complex 34. The plugs-out test was treated as comparatively nonhazardous because the Saturn IB was not fueled. The spacecraft still contained a dense oxygen environment, combustible materials and an escape hatch that could not be opened quickly under pressure.',caution='An unfueled launch vehicle did not mean a safe cabin.',image='https://finalvestige.com/wp-content/uploads/2026/08/s67-19766.webp',alt='Gus Grissom, Ed White and Roger Chaffee near Launch Complex 34 during training in January 1967.',caption='The Apollo 1 crew near Launch Complex 34, January 1967.',asset='NASA S67-19766',credit='NASA',record='https://www.nasa.gov/image-detail/apollo-1-crew-honored/',report=NASA_HIST,kind='DOCUMENTED CONTEXT'),
 dict(id='record-02',eyebrow='THE ATMOSPHERE',when='16.7 PSIA',title='An atmosphere built for a different risk.',dek='One hundred percent oxygen at elevated ground-test pressure greatly increased the fire hazard inside Command Module 012.',detail='The 1967 Review Board documented a 100 percent oxygen cabin atmosphere at 16.7 pounds per square inch absolute during the ground test. Combustible materials and potential ignition sources were present. This was not the same pressure regime the spacecraft would use in orbit.',caution='Oxygen accelerated combustion; it was not itself the ignition spark.',image='https://i0.wp.com/images-assets.nasa.gov/image/S67-15717/S67-15717~large.jpg?resize=1100%2C1400&ssl=1',alt='Apollo Command and Service Module 012 during preflight processing before the Apollo 1 launch-pad fire.',caption='Command Module 012 in processing before the fire.',asset='NASA S67-15717',credit='NASA',record='https://www.nasa.gov/image-detail/amf-s67-15717/',report=REPORT,kind='PRIMARY REVIEW BOARD RECORD'),
 dict(id='record-03',eyebrow='THE SECONDS',when='6:31 P.M.',title='Fourteen seconds changed the system.',dek='The surviving instrument record describes an extraordinarily rapid pressure-and-fire sequence.',detail='The first fire transmission began at approximately 23:31:04.7 GMT. About six seconds later the cabin-pressure sensor showed a clear rise; by approximately 23:31:16 its range was exceeded. The pressure vessel ruptured at least 29 psia around 23:31:19. These timings are approximate marks from the Board account, not a reconstructed second-by-second animation.',caution='The timeline reports observed markers. The intervals between them are not interpolated sensor measurements.',image='https://i0.wp.com/images-assets.nasa.gov/image/S66-58038/S66-58038~large.jpg?resize=1200%2C966&ssl=1',alt='The Apollo 1 crew preparing to enter a command module during preflight training in 1966.',caption='Crew training before the Apollo 1 fire.',asset='NASA S66-58038',credit='NASA',record='https://www.nasa.gov/image-detail/amf-s66-58038/',report=REPORT,kind='INSTRUMENT CHRONOLOGY'),
 dict(id='record-04',eyebrow='THE HATCH',when='DESIGN CONSTRAINT',title='The hatch opened inward.',dek='A seal intended to help contain pressure became an obstacle when pressure rose during the fire.',detail='The Block I command module used an inward-opening pressure hatch. The Review Board found that pressure relief could not keep up with the fire-driven pressure rise, so the hatch could not be opened before the pressure vessel ruptured. Ed White was responsible for opening the hatch; investigators observed movement consistent with an attempt to begin the procedure.',caution='The hatch was one of several interacting hazards, not a standalone explanation of the fire.',image='https://i0.wp.com/images-assets.nasa.gov/image/KSC-20170124-PH_KLS01_0164/KSC-20170124-PH_KLS01_0164~large.jpg?resize=1200%2C800&ssl=1',alt='Apollo 1 tribute displaying the original three-part Block I hatch associated with the command module fire.',caption='Original three-part Block I hatch, shown in the Apollo 1 tribute.',asset='NASA KSC-20170124-PH_KLS01_0164',credit='NASA / Kim Shiflett',record='https://www.nasa.gov/image-detail/amf-ksc-20170124-ph_kls01_0164/',report=REPORT,kind='HARDWARE AND DESIGN FINDING'),
 dict(id='record-05',eyebrow='THE INVESTIGATION',when='1967 REVIEW',title='The spark was never conclusively identified.',dek='Investigators found probable evidence of electrical arcing, but the final ignition source remained unproven.',detail='The Apollo 204 Review Board identified an electrical arc in or near the probable origin area as the most likely initiator. Fire damage destroyed crucial physical evidence; it did not conclusively establish one wire or arc as the ignition source. The Board nevertheless documented vulnerable wiring, combustible materials, the hazardous oxygen environment and inadequate egress provisions.',caution='Probable is not proven. The prototype deliberately keeps this uncertainty visible.',image='https://i0.wp.com/images-assets.nasa.gov/image/S67-21294/S67-21294~large.jpg?resize=1200%2C810&ssl=1',alt='Interior of Apollo Command Module 012 after the January 27, 1967 fire, showing severe heat and fire damage.',caption='The interior of Command Module 012 following the fire.',asset='NASA S67-21294',credit='NASA',record='https://www.nasa.gov/image-detail/amf-s67-21294/',report=REPORT,kind='EVIDENCE BOUNDARY'),
 dict(id='record-06',eyebrow='THE RESPONSE',when='1967–1968',title='Inward became outward.',dek='The redesigned Block II hatch could be opened outward quickly; the safety overhaul extended far beyond the hatch.',detail='NASA replaced the complex inward-opening hatch with an outward-opening, quick-release assembly. It also changed materials, wiring protection, rescue preparation and safety review. The Apollo investigation article notes 102 deliberate ignition tests of Command Module boilerplate 1224 from December 1967 through February 1968—an example of testing how fire would actually spread rather than assuming it could always be prevented.',caution='The improvements were part of a broad redesign; Apollo 1 did not create every safety innovation from nothing.',image='https://i0.wp.com/images-assets.nasa.gov/image/KSC-20170124-PH_KLS01_0090/KSC-20170124-PH_KLS01_0090~large.jpg?resize=900%2C1350&ssl=1',alt='Redesigned unified Apollo hatch developed after the Apollo 1 fire to open outward within seconds.',caption='Redesigned Block II hatch at the Apollo 1 tribute.',asset='NASA KSC-20170124-PH_KLS01_0090',credit='NASA / Kim Shiflett',record='https://www.nasa.gov/image-detail/amf-ksc-20170124-ph_kls01_0090/',report=REPORT,kind='ENGINEERING RESPONSE')
]

